+            } else {
+                timeSeries.add(new ScriptContextStats.TimeSeries());
+            }
+        }
+        return new ScriptContextStats(
+            randomAlphaOfLength(15),
+            histStats[0],
+            histStats[1],
+            randomLongBetween(0, 1024),
+            timeSeries.get(0),
+            timeSeries.get(1)
+        );
