+        }
+        tmp = Files.createTempFile(baseDir, null, null);
+        Files.write(tmp, portFileContent.getBytes(StandardCharsets.UTF_8));
+        Files.move(tmp, baseDir.resolve(PORT_FILE_NAME), StandardCopyOption.ATOMIC_MOVE);
