+     */
+    class Wrapper implements ESCacheHelper {
+
+        private final IndexReader.CacheHelper cacheHelper;
+
+        public Wrapper(IndexReader.CacheHelper cacheHelper) {
+            this.cacheHelper = cacheHelper;
